-- Per-target auxiliary retention leaves business rows outside purge.
ALTER TABLE CFG_TABLES ADD COLUMN REJECT_RETENTION_DAYS INTEGER CHECK (REJECT_RETENTION_DAYS IS NULL OR (typeof(REJECT_RETENTION_DAYS)='integer' AND REJECT_RETENTION_DAYS BETWEEN 1 AND 36500));
ALTER TABLE CFG_TABLES ADD COLUMN SNAPSHOT_RETENTION_DAYS INTEGER CHECK (SNAPSHOT_RETENTION_DAYS IS NULL OR (typeof(SNAPSHOT_RETENTION_DAYS)='integer' AND SNAPSHOT_RETENTION_DAYS BETWEEN 7 AND 36500));
ALTER TABLE CFG_TABLES ADD COLUMN ORPHAN_RETENTION_DAYS INTEGER CHECK (ORPHAN_RETENTION_DAYS IS NULL OR (typeof(ORPHAN_RETENTION_DAYS)='integer' AND ORPHAN_RETENTION_DAYS BETWEEN 7 AND 36500));
ALTER TABLE AUD_CFG_TABLES_HISTORY ADD COLUMN REJECT_RETENTION_DAYS INTEGER CHECK (REJECT_RETENTION_DAYS IS NULL OR (typeof(REJECT_RETENTION_DAYS)='integer' AND REJECT_RETENTION_DAYS BETWEEN 1 AND 36500));
ALTER TABLE AUD_CFG_TABLES_HISTORY ADD COLUMN SNAPSHOT_RETENTION_DAYS INTEGER CHECK (SNAPSHOT_RETENTION_DAYS IS NULL OR (typeof(SNAPSHOT_RETENTION_DAYS)='integer' AND SNAPSHOT_RETENTION_DAYS BETWEEN 7 AND 36500));
ALTER TABLE AUD_CFG_TABLES_HISTORY ADD COLUMN ORPHAN_RETENTION_DAYS INTEGER CHECK (ORPHAN_RETENTION_DAYS IS NULL OR (typeof(ORPHAN_RETENTION_DAYS)='integer' AND ORPHAN_RETENTION_DAYS BETWEEN 7 AND 36500));
CREATE INDEX ix_cfg_tables_warehouse_object ON CFG_TABLES(lower(SCHEMA_NAME),lower(TABLE_NAME),lower(CATALOG_NAME));
